    // Optimized schedules for the per-sweep kernels
    //
    // We operate over the interior domain k = 0 .. n-3 (i = 1 .. n-2),
    // which is a contiguous 1D range, so we can:
    //   - tile in k to form coarse-grain chunks
    //   - parallelize across tiles (each k is independent in a sweep)
    //   - vectorize within tiles to exploit SIMD
    //
    // This preserves the original algorithm:
    //   for each t:
    //     B[1..n-2] = coeff * (A[i-1] + A[i] + A[i+1]);
    //     A[1..n-2] = coeff * (B[i-1] + B[i] + B[i+1]);
    // ------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width =
        target.natural_vector_size(type_of<num_t>());
    // Spatial tile size; chosen to balance parallel granularity and cache use.
    const int tile_k = 256;

    Var ko("ko"), ki("ki");

    // Sweep A -> B
    jacobi_A_to_B
        .compute_root()
        .split(k, ko, ki, tile_k)     // k = ko * tile_k + ki
        .parallel(ko)                 // parallel over tiles
        .vectorize(ki, vec_width);    // SIMD within a tile

    // Sweep B -> A
    jacobi_B_to_A
        .compute_root()
        .split(k, ko, ki, tile_k)
        .parallel(ko)
        .vectorize(ki, vec_width);

