                 A_param(i_center) +
                 A_param(i_center + 1));

    // One Jacobi sweep: B -> A (compute A[i] from neighbors of B[i]).
    Func jacobi_B_to_A("jacobi_B_to_A");
    jacobi_B_to_A(k) =
        coeff * (B_param(i_center - 1) +
                 B_param(i_center) +
                 B_param(i_center + 1));

    // ------------------------------------------------------------------
    // Optimized schedules
    //
    // The computation for a fixed time step is:
    //   - Pure 1D stencil over the interior points k = 0 .. n-3
    //   - Reads from A (or B) and writes to B (or A)
    //   - No loop-carried dependences across k within a sweep
    //
    // This makes it safe to:
    //   * tile k into chunks,
    //   * parallelize across tiles, and
