#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, N, TSTEPS, etc.)
#include "defines.hpp"
// Benchmark-specific definitions for jacobi-1d (N, TSTEPS, etc.)
#include "jacobi-1d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Halide-based initialization of A and B.
static void init_array(int n,
                       Halide::Buffer<num_t, 1> A,
                       Halide::Buffer<num_t, 1> B) {
    Var i("i");
    Func init_A("init_A"), init_B("init_B");

    // A[i] = ((DATA_TYPE) i + 2) / n;
    init_A(i) = cast<num_t>(i + 2) / cast<num_t>(n);

    // B[i] = ((DATA_TYPE) i + 3) / n;
    init_B(i) = cast<num_t>(i + 3) / cast<num_t>(n);

    // ------------------------------------------------------------------
    // Optimized schedule for initialization
    //
    // Initialization is a simple, embarrassingly parallel 1D loop over i.
    // We:
    //   * tile i to form coarse-grain chunks,
    //   * parallelize across tiles,
    //   * vectorize within each tile.
    // ------------------------------------------------------------------
    const int init_tile_size  = 1024; // coarse-grain parallelism
    const int init_vec_width  = 8;    // SIMD width (tuned for typical AVX2 floats)

    Var io("io"), ii("ii");
    init_A
        .compute_root()
        .split(i, io, ii, init_tile_size)
        .parallel(io)
        .vectorize(ii, init_vec_width);

    init_B
        .compute_root()
        .split(i, io, ii, init_tile_size)
        .parallel(io)
        .vectorize(ii, init_vec_width);

    // Realize into the provided buffers.
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate 1D buffers A and B of length n.
    Halide::Buffer<num_t, 1> A(n);
    Halide::Buffer<num_t, 1> B(n);

    // Initialize A and B.
    init_array(n, A, B);

    // ImageParams used as inputs to the per-time-step Halide kernels.
    ImageParam A_param(type_of<num_t>(), 1, "A_param");
    ImageParam B_param(type_of<num_t>(), 1, "B_param");

    // Var for the interior index (0 .. n-3), corresponding to i = k+1 in C.
    Var k("k");

    // Center index in the original array: i = k + 1 (i runs from 1 .. n-2).
    Expr i_center = k + 1;

    // Constant factor 0.33333 cast to num_t.
    Expr coeff = cast<num_t>(Expr(0.33333));

    // ----------------------------------------------------------------------
    // Per-sweep Jacobi stencils (pure Funcs, no loop-carried dependencies).
    //
    // For fixed time step t:
    //   First half-step:  A -> B  (update interior of B from A)
    //   Second half-step: B -> A  (update interior of A from B)
    //
    // We only define the spatial stencil here; time-stepping is done by
    // the host C++ loop with double-buffering (A and B), which is the
    // recommended pattern for this kind of recurrence in Halide.
    // ----------------------------------------------------------------------

    // One Jacobi sweep: A -> B (compute B[i] from neighbors of A[i]).
    Func jacobi_A_to_B("jacobi_A_to_B");
    jacobi_A_to_B(k) =
        coeff * (A_param(i_center - 1) +
                 A_param(i_center) +
                 A_param(i_center + 1));

    // One Jacobi sweep: B -> A (compute A[i] from neighbors of B[i]).
    Func jacobi_B_to_A("jacobi_B_to_A");
    jacobi_B_to_A(k) =
        coeff * (B_param(i_center - 1) +
                 B_param(i_center) +
                 B_param(i_center + 1));

    // ----------------------------------------------------------------------
    // Optimized schedules for the Jacobi sweeps
    //
    // Domain of k: 0 .. (n-3), corresponding to interior indices i = 1..n-2.
    //
    // For each sweep we:
    //   * tile k to form cache- and thread-friendly blocks,
    //   * parallelize across tiles (safe: each k writes a distinct element
    //     and reads only from the input ImageParam),
    //   * vectorize within each tile along contiguous k.
    //
    // This exposes both coarse-grain parallelism (across tiles) and
    // fine-grain SIMD parallelism (within a tile), while preserving
    // the original sequential time-stepping in the outer C++ loop.
    // ----------------------------------------------------------------------
    const int tile_size   = 1024; // spatial tile size (tunable)
    const int vec_width   = 8;    // SIMD width (tunable; 8 works well for float)

    Var ko("ko"), ki("ki");

    jacobi_A_to_B
        .compute_root()
        .split(k, ko, ki, tile_size)
        .parallel(ko)          // parallelize across tiles
        .vectorize(ki, vec_width); // SIMD within each tile

    jacobi_B_to_A
        .compute_root()
        .split(k, ko, ki, tile_size)
        .parallel(ko)
        .vectorize(ki, vec_width);

    // Bind the interior [1 .. n-2] of A and B to contiguous Halide Buffers.
    // k runs from 0 .. n-3; k == 0 corresponds to element index 1.
    Halide::Buffer<num_t, 1> A_interior(A.data() + 1, n - 2);
    Halide::Buffer<num_t, 1> B_interior(B.data() + 1, n - 2);

    // JIT-compile the per-sweep kernels once.
    jacobi_A_to_B.compile_jit();
    jacobi_B_to_A.compile_jit();

    // Time the Jacobi iterations (the main kernel).
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // First half-step: A -> B (update B[1..n-2] from A).
        A_param.set(A);
        jacobi_A_to_B.realize(B_interior);

        // Second half-step: B -> A (update A[1..n-2] from B).
        B_param.set(B);
        jacobi_B_to_A.realize(A_interior);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the output array A to stderr (to mimic PolyBench DCE).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < n; i++) {
            std::cerr << A(i) << '\n';
        }
    }

    // Print the elapsed time (in seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
